from pathlib import Path

path = Path('/Users/vince/sTIMulation/templates/index.html')
text = path.read_text()

old = """function drawVehicle(x,y,angle,color,state,alpha=1,vid){ctx.save();ctx.globalAlpha=alpha;ctx.translate(x,y);ctx.rotate(angle-Math.PI/2);const carSprite=vid%2===0?CAR1_SPRITE:CAR2_SPRITE,carReady=vid%2===0?CAR1_READY:CAR2_READY;if(carReady&&carSprite.naturalWidth>0){const spriteH=24,ratio=carSprite.naturalWidth/carSprite.naturalHeight||1,spriteW=spriteH*ratio;ctx.drawImage(carSprite,-spriteW/2,-spriteH/2,spriteW,spriteH);if(state==='moving'){const frontY=-spriteH/2-2;ctx.fillStyle='#fffacd';ctx.globalAlpha=alpha*.96;ctx.beginPath();ctx.arc(0,frontY,2.8,0,Math.PI*2);ctx.fill();ctx.globalAlpha=alpha;ctx.fillStyle='rgba(255,250,205,.14)';ctx.beginPath();ctx.moveTo(0,frontY+1);ctx.quadraticCurveTo(0,frontY-10,-10,frontY-22);ctx.lineTo(-32,frontY-16);ctx.lineTo(-28,frontY+16);ctx.quadraticCurveTo(-10,frontY+10,0,frontY+4);ctx.closePath();ctx.fill();ctx.fillStyle='rgba(255,250,205,.22)';ctx.beginPath();ctx.arc(0,frontY+2,10,0,Math.PI*2);ctx.fill();}}else{ctx.fillStyle=color;roundRect(-9,-5.5,18,11,2.5);ctx.fill();ctx.fillStyle=color+'cc';roundRect(-5,-4,9,8,2);ctx.fill();ctx.fillStyle='rgba(200,230,255,.35)';roundRect(-5,-3.5,7,7,1.5);ctx.fill();ctx.fillStyle='rgba(200,230,255,.2)';roundRect(4,-3,3.5,6,1);ctx.fill();if(state==='moving'){ctx.fillStyle='#ffffc0dd';roundRect(-9.5,-4,3,2.5,1);ctx.fill();roundRect(-9.5,1.5,3,2.5,1);ctx.fill();ctx.fillStyle='rgba(255,255,180,.06)';ctx.beginPath();ctx.moveTo(-9,0);ctx.lineTo(-45,-14);ctx.lineTo(-45,14);ctx.closePath();ctx.fill();}else{ctx.fillStyle='#ff3333cc';roundRect(7,-4,2.5,2.5,.8);ctx.fill();roundRect(7,1.5,2.5,2.5,.8);ctx.fill();}}ctx.restore();}\n"""

new = """function drawVehicle(x,y,angle,color,state,alpha=1,vid){ctx.save();ctx.globalAlpha=alpha;ctx.translate(x,y);ctx.rotate(angle-Math.PI/2);const carSprite=vid%2===0?CAR1_SPRITE:CAR2_SPRITE,carReady=vid%2===0?CAR1_READY:CAR2_READY;if(carReady&&carSprite.naturalWidth>0){const spriteH=24,ratio=carSprite.naturalWidth/carSprite.naturalHeight||1,spriteW=spriteH*ratio;ctx.drawImage(carSprite,-spriteW/2,-spriteH/2,spriteW,spriteH);}else{ctx.fillStyle=color;roundRect(-9,-5.5,18,11,2.5);ctx.fill();ctx.fillStyle=color+'cc';roundRect(-5,-4,9,8,2);ctx.fill();ctx.fillStyle='rgba(200,230,255,.35)';roundRect(-5,-3.5,7,7,1.5);ctx.fill();ctx.fillStyle='rgba(200,230,255,.2)';roundRect(4,-3,3.5,6,1);ctx.fill();if(state==='moving'){ctx.fillStyle='#ffffc0dd';roundRect(-9.5,-4,3,2.5,1);ctx.fill();roundRect(-9.5,1.5,3,2.5,1);ctx.fill();ctx.fillStyle='rgba(255,255,180,.06)';ctx.beginPath();ctx.moveTo(-9,0);ctx.lineTo(-45,-14);ctx.lineTo(-45,14);ctx.closePath();ctx.fill();}else{ctx.fillStyle='#ff3333cc';roundRect(7,-4,2.5,2.5,.8);ctx.fill();roundRect(7,1.5,2.5,2.5,.8);ctx.fill();}}ctx.restore();}\n"""

if old not in text:
    raise SystemExit('light block not found')
text = text.replace(old, new)
path.write_text(text)
print('removed car lights')
